"""Permutation in String — fixed-window anagram check.

Time: O(n)   Space: O(1)
"""
from collections import Counter


class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        n = len(s1)
        if n > len(s2):
            return False
        need = Counter(s1)
        window = Counter(s2[:n])
        if window == need:
            return True
        for i in range(n, len(s2)):
            window[s2[i]] += 1
            left = s2[i - n]
            window[left] -= 1
            if window[left] == 0:
                del window[left]
            if window == need:
                return True
        return False
